"""
scada_symbol_catalog.py - Comprehensive Industrial SCADA & P&ID Vector Symbol Library
Supplies 250+ precision SVG engineering symbols across 10 equipment categories:
1. Pumps (Centrifugal, Positive Displacement, Submersible, Assemblies)
2. Valves (Isolation, Throttling, Check, Actuated, Safety, Multi-port)
3. Tanks & Vessels (Storage, Separation, Pressure, Towers, Agitated)
4. Rotating Equipment (Motors, Compressors, Turbines, Fans, Blowers, Agitators)
5. Thermal Equipment (Boilers, Heat Exchangers, Cooling Towers, Furnaces, Chillers)
6. Instrumentation (Transmitters, Switches, Analyzers, Local Gauges, Probes)
7. Piping & Fittings (Lines, Elbows, Tees, Reducers, Strainers, Traps, Flanges)
8. Electrical (Transformers, Breakers, VFDs, MCCs, UPS, Switchgear)
9. Material Handling (Conveyors, Elevators, Crushers, Feeders, Presses)
10. HMI Elements (Digital Displays, Radial Gauges, Level Bars, Status Beacons, Buttons)
"""
from typing import List, Dict, Any

# Helper to generate connection ports
def make_ports(ports_spec):
    return [
        {
            "id": p[0],
            "name": p[1],
            "x": p[2],
            "y": p[3],
            "direction": p[4], # "LEFT", "RIGHT", "TOP", "BOTTOM"
            "type": p[5]       # "INLET", "OUTLET", "BIDIRECTIONAL", "SIGNAL", "ELECTRICAL"
        }
        for p in ports_spec
    ]

